<section class="filter-bar"><form method="get" class="login-attempt-filter"><input type="hidden" name="tab" value="login_security"><div class="field"><label for="security_ip">精确IP</label><input class="control" id="security_ip" name="ip" value="<?= e($securityFilters['ip']) ?>"></div><div class="field"><label for="security_admin">管理员</label><select class="control" id="security_admin" name="admin_id"><option value="">全部管理员</option><?php foreach ($securityAdminOptions as $option): ?><option value="<?= (int) $option['id'] ?>" <?= (string) $securityFilters['admin_id'] === (string) $option['id'] ? 'selected' : '' ?>><?= e($option['username']) ?></option><?php endforeach; ?></select></div><div class="field"><label for="security_result">登录结果</label><select class="control" id="security_result" name="result"><option value="">全部</option><option value="1" <?= $securityFilters['result'] === '1' ? 'selected' : '' ?>>成功</option><option value="0" <?= $securityFilters['result'] === '0' ? 'selected' : '' ?>>失败</option></select></div><details class="advanced-filter"><summary>更多筛选</summary><div class="advanced-filter-grid"><div class="field"><label for="security_reason">失败原因</label><select class="control" id="security_reason" name="reason"><option value="">全部原因</option><?php foreach ($loginFailureLabels as $value => $label): ?><option value="<?= e($value) ?>" <?= $securityFilters['reason'] === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="field"><label for="security_start">开始日期</label><input class="control" type="date" id="security_start" name="start_date" value="<?= e($securityFilters['start_date']) ?>"></div><div class="field"><label for="security_end">结束日期</label><input class="control" type="date" id="security_end" name="end_date" value="<?= e($securityFilters['end_date']) ?>"></div></div></details><div class="filter-actions"><button class="btn btn-primary" type="submit">筛选</button><a class="btn btn-ghost" href="<?= e(admin_page_