<section class="panel"><div class="panel-heading"><div><h2>登录安全记录</h2><p>不保存明文登录标识、密码或完整手机号。</p></div></div><?php if ($loginAttemptPage['attempts'] === []): ?><div class="empty-state compact"><?= admin_icon('logs') ?><h3>暂无登录记录</h3></div><?php else: ?><div class="desktop-table"><div class="table-wrap"><table><thead><tr><th>时间</th><th>管理员</th><th>IP</th><th>结果</th><th>原因</th><th>设备</th></tr></thead><tbody><?php foreach ($loginAttemptPage['attempts'] as $attempt): ?><tr><td><?= e($attempt['created_at']) ?></td><td><?= e($attempt['username'] ?? '未知账号') ?></td><td><?= e($attempt['ip_plain'] ?: '历史记录未保存') ?></td><td><span class="badge badge-<?= (int) $attempt['is_success'] ? 'success' : 'failed' ?>"><?= (int) $attempt['is_success'] ? '成功' : '失败' ?></span></td><td><?= e($loginFailureLabels[$attempt['failure_reason']] ?? $attempt['failure_reason']) ?></td><td><?= e($attempt['device_type']) ?> · <?= e($attempt['browser_name']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="mobile-cards"><?php foreach ($loginAttemptPage['attempts'] as $attempt): ?><article class="mobile-list-card"><div class="mobile-card-head"><strong><?= e($attempt['username'] ?? '未知账号') ?></strong><span class="badge badge-<?= (int) $attempt['is_success'] ? 'success' : 'failed' ?>"><?= (int) $attempt['is_success'] ? '成功' : '失败' ?></span></div><dl class="record-preview"><div><dt>时间</dt><dd><?= e($attempt['created_at']) ?></dd></div><div><dt>IP</dt><dd><?= e($attempt['ip_plain'] ?: '历史记录未保存') ?></dd></div><div><dt>原因</dt><dd><?= e($loginFailureLabels[$attempt['failure_reason']] ?? $attempt['failure_reason']) ?></dd></div></dl></article><?php endforeach; ?></div><?php endif; ?></section>
